const paths={home:'m3 11 9-8 9 8v10h-6v-7H9v7H3z',search:'M21 21l-6-6M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',user:'M20 22v-3a8 8 0 0 0-16 0v3zM17 6a5 5 0 1 1-10 0 5 5 0 0 1 10 0',cart:'M2 3h3l3 13h12l2-10H6M10 21h.01M19 21h.01',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',mic:'M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3M6 10v2a6 6 0 0 0 12 0v-2M12 18v4M9 22h6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.heart}"/></svg>`;function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.outerHTML=icon(e.dataset.icon))}
const products=[{id:1,name:'쌀가루 플레인 스콘',cat:'스콘',img:'scone',tags:['비건','글루텐프리','저당'],desc:'겉은 바삭하고 속은 포근한 쌀가루 스콘. 담백한 고소함으로 채우는 나만의 간식 시간.',price:3800,kcal:185,sugar:3},{id:2,name:'초코 머핀',cat:'머핀',img:'muffin',tags:['난류 제외','저당'],desc:'진한 초콜릿의 풍미와 촉촉한 식감. 달콤한 휴식이 필요할 때 만나보세요.',price:4200,kcal:210,sugar:5},{id:3,name:'오트 초코칩 쿠키',cat:'쿠키',img:'cookie',tags:['비건','저당'],desc:'오트의 고소함에 초콜릿을 더한 바삭한 쿠키.',price:2900,kcal:160,sugar:4},{id:4,name:'담백한 쌀 브레드',cat:'브레드',img:'bread',tags:['비건','글루텐프리'],desc:'천천히 즐기고 싶은 부드럽고 담백한 한 조각.',price:6500,kcal:190,sugar:2},{id:5,name:'딸기 시즌 케이크',cat:'시즌',img:'cake',tags:['난류 제외'],desc:'상큼한 딸기와 부드러운 크림으로 완성하는 계절의 맛.',price:7200,kcal:265,sugar:14}];
const cats=[['스콘','🥮'],['쿠키','🍪'],['머핀','🧁'],['브레드','🍞'],['시즌','🍰']];let favorites=JSON.parse(localStorage.getItem('wishme-favorites')||'[]'),diet=JSON.parse(localStorage.getItem('wishme-diet')||'["비건","글루텐프리","저당"]'),cart=JSON.parse(localStorage.getItem('wishme-cart')||'[]'),page='home',category='',query='';const main=document.querySelector('main'),modal=document.querySelector('dialog');
function save(){localStorage.setItem('wishme-favorites',JSON.stringify(favorites));localStorage.setItem('wishme-diet',JSON.stringify(diet));localStorage.setItem('wishme-cart',JSON.stringify(cart));const n=document.querySelector('#cart-count');n.textContent=cart.length;n.hidden=!cart.length}
const chips=()=>`<div class="chips">${diet.length?diet.map((d,i)=>`<span class="chip"><span class="leaf">${['❧','♧','♧'][i%3]}</span>${d}</span>`).join(''):'<button class="chip" data-action="diet">식이조건 추가 +</button>'}</div>`;
const categories=()=>`<div class="categories">${cats.map(([c,emoji])=>`<button class="category ${category===c?'active':''}" data-cat="${c}" aria-pressed="${category===c}"><span class="food">${emoji}</span>${c}</button>`).join('')}</div>`;
function cards(list){return `<div class="products">${list.length?list.map(p=>`<article class="product"><img class="product-image" src="assets/${p.img}.jpg" alt="${p.name}" data-detail="${p.id}"><button class="favorite ${favorites.includes(p.id)?'selected':''}" data-fav="${p.id}" aria-label="${p.name} 찜" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button><div class="product-info"><h3>${p.name}</h3><p class="tags">${p.tags.join(' · ')}</p><button class="detail-btn" data-detail="${p.id}">자세히 보기 <span>›</span></button></div></article>`).join(''):`<div class="empty">${icon('search')}<br>조건에 맞는 간식이 아직 없어요.<br>다른 메뉴나 검색어로 찾아보세요.</div>`}</div>`}
const searchbar=()=>`<form class="searchbar"><input aria-label="간식 검색" placeholder="쌀가루로 만든 덜 단 스콘을 찾고 있어요" value=""><button class="mic" type="button" data-action="voice" aria-label="음성 검색">${icon('mic')}</button><button class="submit" aria-label="검색">${icon('search')}</button></form>`;
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')main.innerHTML=`<div class="hero"><h1>오늘은 어떤 간식이<br>먹고 싶나요?</h1></div>${searchbar()}<section class="section"><div class="section-head"><h2>메뉴에서 바로 고르기</h2></div>${categories()}</section><section class="section"><div class="section-head"><h2>내 식이조건</h2><button class="text-btn" data-action="diet">수정 ›</button></div>${chips()}</section><section class="section recommend"><div class="section-head"><h2>맞춤 추천<span class="spark">〃</span></h2><button class="text-btn" data-page="menu">더 보기 ›</button></div>${cards(category?products.filter(p=>p.cat===category):[...products].sort((a,b)=>b.tags.filter(t=>diet.includes(t)).length-a.tags.filter(t=>diet.includes(t)).length).slice(0,2))}</section>`;
else if(page==='menu'||page==='search'){let list=products.filter(p=>(!category||p.cat===category));if(query){const words=query.replace(/찾고|있어요|만든|덜|단|으로|로|을|를|먹고|싶어요/g,' ').split(/\s+/).filter(w=>w.length>1);list=list.filter(p=>words.some(w=>(p.name+p.tags.join('')).includes(w)))}main.innerHTML=`<div class="page-intro"><h1>${page==='menu'?'오늘의 간식 메뉴':'내게 맞는 간식 찾기'}</h1><p>${page==='menu'?'작은 한 입에도, 나를 생각하는 선택.':'먹고 싶은 간식이나 식이조건을 알려주세요.'}</p></div>${searchbar()}<section class="section">${categories()}<div class="section-head" style="margin-top:25px"><h2>${query?'검색 결과':category||'모든 간식'} <small style="color:#87936c">${list.length}</small></h2><button class="text-btn" data-action="reset">전체 보기 ↺</button></div>${cards(list)}</section>`;document.querySelector('.searchbar input').value=query}
else if(page==='favorites')main.innerHTML=`<div class="page-intro"><h1>내가 찜한 간식</h1><p>마음에 담아둔 맛있는 순간들.</p></div><section class="section">${favorites.length?cards(products.filter(p=>favorites.includes(p.id))):`<div class="empty">${icon('heart')}<br>아직 찜한 간식이 없어요.<br>마음에 드는 간식의 하트를 눌러주세요.</div>`}<button class="primary" data-action="cart">장바구니 보기 (${cart.length})</button></section>`;
else main.innerHTML=`<div class="page-intro"><h1>나를 위한 WISHME</h1><p>내 취향에 조금 더 가까이.</p></div><section class="profile"><h2>안녕하세요, 위시미님 🌿</h2><p>오늘도 나에게 맞는 달콤함을 찾아보세요.</p><button class="list-item" data-action="diet">내 식이조건 설정 <span>›</span></button><button class="list-item" data-page="favorites">찜한 간식 <span>${favorites.length} ›</span></button><button class="list-item" data-action="cart">장바구니 <span>${cart.length} ›</span></button></section><section class="section">${chips()}</section>`;main.insertAdjacentHTML('beforeend','<p class="note">먹고 싶은 걸, 내게 맞게. WISHME<br>체험용 프로토타입 · 상품 및 영양정보는 예시입니다.</p>');save()}
function open(content,title=''){document.querySelector('#modal-content').innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="close" aria-label="닫기">×</button></div><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal()}
function toast(t){const e=document.querySelector('.toast');e.textContent=t;e.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>e.classList.remove('show'),2300)}
function showCart(){open(cart.length?cart.map((id,i)=>{let p=products.find(p=>p.id===id);return `<div class="cart-row"><img src="assets/${p.img}.jpg" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.price.toLocaleString()}원</p></div><button class="remove" data-remove="${i}" aria-label="${p.name} 삭제">×</button></div>`}).join('')+`<div class="price">합계 ${cart.reduce((a,id)=>a+products.find(p=>p.id===id).price,0).toLocaleString()}원</div><button class="primary" data-action="checkout">주문 체험하기</button><p class="note">실제 결제는 진행되지 않습니다.</p>`:'<div class="empty">장바구니가 비어 있어요.<br>마음에 드는 간식을 담아보세요.</div>','장바구니')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b){const img=e.target.closest('[data-detail]');if(img)detail(+img.dataset.detail);return}if(b.classList.contains('brand')){e.preventDefault();page='home';category='';query='';render();window.scrollTo(0,0)}if(b.dataset.page){page=b.dataset.page;query='';category='';render();window.scrollTo(0,0);if(page==='search')document.querySelector('input').focus()}if(b.dataset.cat){category=category===b.dataset.cat?'':b.dataset.cat;render()}if(b.dataset.detail)detail(+b.dataset.detail);if(b.dataset.fav){let id=+b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];render();toast(favorites.includes(id)?'찜한 간식에 담았어요':'찜 목록에서 삭제했어요')}if(b.classList.contains('close'))modal.close();if(b.dataset.add){cart.push(+b.dataset.add);save();modal.close();toast('장바구니에 담았어요')}if(b.dataset.remove!==undefined){cart.splice(+b.dataset.remove,1);save();showCart()}switch(b.dataset.action){case'diet':open(`<p>나에게 맞는 조건을 선택해주세요.<br>선택한 조건은 이 브라우저에 저장됩니다.</p>${['비건','글루텐프리','저당','난류 제외','유제품 제외'].map(d=>`<label class="check-row"><input type="checkbox" value="${d}" ${diet.includes(d)?'checked':''}>${d}</label>`).join('')}<button class="primary" data-action="save-diet">저장하기</button>`,'내 식이조건');break;case'save-diet':diet=[...modal.querySelectorAll('input:checked')].map(x=>x.value);save();render();modal.close();toast('식이조건을 저장했어요');break;case'cart':showCart();break;case'checkout':open('<div class="empty">🌿<h2>주문 흐름을 체험했어요!</h2>실제 주문과 결제는 발생하지 않습니다.<br>다른 간식도 천천히 둘러보세요.</div><button class="primary close">계속 둘러보기</button>','주문 체험 완료');break;case'notifications':open('<h3>나에게 맞는 달콤함을 만나보세요 🌿</h3><p>새로운 간식이 준비되었어요. 오늘의 추천 메뉴를 확인해보세요.</p><p class="note">예시 알림</p>','알림');break;case'reset':query='';category='';render();break;case'voice':voice();break}});
function detail(id){const p=products.find(p=>p.id===id);open(`<img src="assets/${p.img}.jpg" alt="${p.name}"><h2>${p.name}</h2><div class="tags">${p.tags.join(' · ')}</div><p>${p.desc}</p><div class="nutrition"><span>열량<b>${p.kcal} kcal</b></span><span>당류<b>${p.sugar} g</b></span><span>기준<b>1개</b></span></div><div class="price">${p.price.toLocaleString()}원</div><button class="primary" data-add="${id}">장바구니 담기</button><p class="note">프로토타입용 예시 정보입니다.</p>`,'오늘의 간식')}
document.addEventListener('submit',e=>{if(e.target.matches('.searchbar')){e.preventDefault();query=e.target.querySelector('input').value.trim();category='';page='search';render()}});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function voice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('이 브라우저에서는 텍스트로 검색해주세요');document.querySelector('.searchbar input').focus();return}const r=new Speech();r.lang='ko-KR';r.onresult=e=>{query=e.results[0][0].transcript;page='search';category='';render()};r.onerror=()=>toast('음성을 듣지 못했어요. 텍스트로 검색해주세요');try{r.start();toast('찾고 싶은 간식을 말씀해주세요')}catch{toast('텍스트로 검색해주세요')}}icons();render();
